TargetContent:
"                          <span className={`text-[10px] font-black uppercase tracking-wider ${subOrderType === 'DELIVERY' ? 'text-[#18ba60] font-black' : (isDark ? 'text-[#8b949e]' : 'text-slate-400')}`}>Delivery</span>

                          {/* Rider Select Dropdown for Delivery */}
                          {subOrderType === 'DELIVERY' && (
                            <select
                              value={selectedRiderId}
                              onChange={(e) => setSelectedRiderId(e.target.value)}
                              className={`p-1 rounded font-bold text-[10px] outline-none cursor-pointer max-w-[120px] transition-colors border ${
                                isDark ? 'bg-[#161b22] border-[#30363d] text-white focus:border-[#10ac84]' : 'bg-[#f1f3f4] border-slate-300 text-slate-800 focus:border-[#388e67]'
                              }`}
                            >
                              <option value="">Select Rider</option>
                              {riders.map(r => (
                                <option key={r.id} value={r.id}>
                                  {r.name}
                                </option>
                              ))}
                            </select>
                          )}"
